func BuildInstance(
	externalID string,
	deploymentID uuid.UUID,
	releaseID uuid.UUID,
	environmentTargetID uuid.UUID,
	opts ...InstanceOption,
) models.InstanceEntity {
	f := &InstanceFactory{
		InstanceEntity: models.InstanceEntity{
			ExternalID:          externalID,
			Slot:                faker.Word(),
			ReplicaKey:          faker.Word(),
			State:               faker.Word(),
			Ports:               json.RawMessage{},
			ObservedAt:          time.Time{},
			RemovedAt:           sql.NullTime{Time: time.Now(), Valid: true},
			DeploymentID:        deploymentID,
			ReleaseID:           releaseID,
			EnvironmentTargetID: environmentTargetID,
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.InstanceEntity
}

func CreateInstance(
	ctx context.Context,
	exec storage.Executor,
	externalID string,
	deploymentID uuid.UUID,
	releaseID uuid.UUID,
	environmentTargetID uuid.UUID,
	opts ...InstanceOption,
) (models.InstanceEntity, error) {
	built := BuildInstance(externalID, deploymentID, releaseID, environmentTargetID, opts...)

	entity := models.InstanceEntity{
		ID:                  uuid.New(),
		CreatedAt:           time.Now(),
		UpdatedAt:           time.Now(),
		ExternalID:          built.ExternalID,
		Slot:                built.Slot,
		ReplicaKey:          built.ReplicaKey,
		State:               built.State,
		Ports:               built.Ports,
		ObservedAt:          built.ObservedAt,
		RemovedAt:           built.RemovedAt,
		DeploymentID:        built.DeploymentID,
		ReleaseID:           built.ReleaseID,
		EnvironmentTargetID: built.EnvironmentTargetID,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.InstanceEntity{}, err
	}

	return entity, nil
}

func CreateInstances(
	ctx context.Context,
	exec storage.Executor,
	externalID string,
	deploymentID uuid.UUID,
	releaseID uuid.UUID,
	environmentTargetID uuid.UUID,
	count int,
	opts ...InstanceOption,
) ([]models.InstanceEntity, error) {
	instances := make([]models.InstanceEntity, 0, count)

	for i := range count {
		entity, err := CreateInstance(
			ctx,
			exec,
			externalID,
			deploymentID,
			releaseID,
			environmentTargetID,
			opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create instance %d: %w", i+1, err)
		}
		instances = append(instances, entity)
	}

	return instances, nil
}

